// Node: Build Search Queries (runOnceForAllItems)
// Edit this list to change what is searched. One item = one Serper request.
// No API keys here. The Serper key lives in an n8n credential.
const SEARCHES = [
  { country: 'United Kingdom', gl: 'uk', query: 'independent skincare online store CeraVe La Roche-Posay The Ordinary UK' },
  { country: 'United States', gl: 'us', query: 'independent skincare online store CeraVe La Roche-Posay COSRX The Ordinary US' },
  { country: 'Canada', gl: 'ca', query: 'independent skincare online store CeraVe La Roche-Posay Anua COSRX Canada' },
  { country: 'Australia', gl: 'au', query: 'independent skincare online store CeraVe La Roche-Posay The Ordinary Australia' },
];

return SEARCHES.map((s) => ({ json: { ...s } }));

// Node: Parse Search Results (runOnceForAllItems)
// Input: one item per Serper HTTP response, in the same order as the query items.
// Output: one item per organic result. Failed requests become error items (not dropped).
const queries = $('Build Search Queries').all();
const responses = $input.all();
const today = new Date().toISOString().slice(0, 10);
const out = [];

responses.forEach((resp, i) => {
  const meta = queries[i] ? queries[i].json : {};
  const body = resp.json || {};

  if (body.error) {
    out.push({ json: {
      parse_error: true,
      error_type: 'serper_request_failed',
      error_message: String(body.error.message || body.error),
      country: meta.country,
      search_query: meta.query,
    } });
    return;
  }

  const organic = Array.isArray(body.organic) ? body.organic : [];
  if (organic.length === 0) {
    out.push({ json: {
      parse_error: true,
      error_type: 'serper_no_organic_results',
      error_message: 'Serper returned no organic results for this query',
      country: meta.country,
      search_query: meta.query,
    } });
    return;
  }

  organic.forEach((r, pos) => {
    out.push({ json: {
      parse_error: false,
      // The search title is only a provisional name. Enrichment may replace it.
      company_name: String(r.title || '').trim(),
      website: String(r.link || '').trim(),
      snippet: String(r.snippet || '').trim(),
      country: meta.country,
      search_query: meta.query,
      source_url: String(r.link || '').trim(),
      discovery_source: 'serper_organic',
      discovery_position: r.position ?? pos + 1,
      discovery_date: today,
    } });
  });
});

return out;

// Node: Normalise Website and Domain (runOnceForEachItem)
// Version 3: no built-in URL class. A regular expression splits the URL instead.
const MULTI_PART_SUFFIXES = new Set([
  'co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'me.uk', 'net.uk',
  'com.au', 'net.au', 'org.au', 'edu.au', 'gov.au',
  'co.nz', 'co.za', 'com.ng',
]);

const lead = $input.item.json;

const fail = (errorType, message, status = 'invalid_url') => ({ json: {
  ...lead,
  is_valid_domain: false,
  error_type: errorType,
  error_message: message,
  processing_status: status,
} });

// A search result that never produced a link is not a URL problem.
if (lead.parse_error) {
  return fail(
    lead.error_type,
    'Search result problem: ' + (lead.error_message || lead.error_type),
    'search_error'
  );
}

// Remove invisible characters, then trim.
const raw = String(lead.website ?? '')
  .replace(/[\u0000-\u001F\u007F-\u009F\u00A0\u200B-\u200D\uFEFF]/g, '')
  .trim();

if (!raw) {
  return fail('malformed_url', 'Website normalisation failed: malformed_url (empty URL)');
}

// Pattern: scheme://host[:port][/path][?query][#fragment]
const match = raw.match(/^(https?):\/\/([^\/?#\s]+)/i);
if (!match) {
  return fail(
    'malformed_url',
    'Website normalisation failed: malformed_url (raw value: ' + raw.slice(0, 200) + ')'
  );
}

// Remove any user:password@ part and any :port, lowercase, strip "www." and a trailing dot.
const host = match[2]
  .replace(/^.*@/, '')
  .replace(/:\d+$/, '')
  .toLowerCase()
  .replace(/\.$/, '')
  .replace(/^www\./, '');

if (/^\d+(\.\d+)*$/.test(host)) {
  return fail('ip_address_not_allowed', 'Website normalisation failed: ip_address_not_allowed');
}
if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host)) {
  return fail('no_registrable_domain', 'Website normalisation failed: no_registrable_domain (host: ' + host.slice(0, 100) + ')');
}

const labels = host.split('.');

// Registrable domain: last 2 labels, or last 3 for known multi-part suffixes (glow.co.uk).
const last2 = labels.slice(-2).join('.');
let canonical = last2;
if (MULTI_PART_SUFFIXES.has(last2)) {
  if (labels.length < 3) {
    return fail('no_registrable_domain', 'Website normalisation failed: no_registrable_domain');
  }
  canonical = labels.slice(-3).join('.');
}

return { json: {
  ...lead,
  is_valid_domain: true,
  website: 'https://' + host,
  canonical_domain: canonical,
  source_url: lead.source_url || raw,
  normalise_status: 'ok',
} };

// Node: Remove Same-Batch Duplicates (runOnceForAllItems)
// Merges search results that point to the same canonical_domain within one run.
// Keeps the first record's fields and merges the evidence URLs and snippets.
// Invalid items pass through unchanged so the IF node can route them to the log.
const items = $input.all().map((i) => i.json);
const groups = new Map();
const out = [];

for (const lead of items) {
  if (!lead.is_valid_domain) {
    out.push({ json: lead });
    continue;
  }

  const key = lead.canonical_domain;

  if (groups.has(key)) {
    const g = groups.get(key);
    g.duplicates_merged += 1;
    if (lead.source_url && !g.discovery_urls.includes(lead.source_url)) g.discovery_urls.push(lead.source_url);
    if (lead.snippet && !g.snippets.includes(lead.snippet)) g.snippets.push(lead.snippet);
    if (lead.country && !g.countries.includes(lead.country)) g.countries.push(lead.country);
    continue;
  }

  groups.set(key, {
    ...lead,
    discovery_urls: lead.source_url ? [lead.source_url] : [],
    snippets: lead.snippet ? [lead.snippet] : [],
    countries: lead.country ? [lead.country] : [],
    duplicates_merged: 0,
    processing_status: 'discovered',
  });
}

for (const g of groups.values()) {
  out.push({ json: {
    ...g,
    evidence_urls: g.discovery_urls.join('\n'),
    snippet: g.snippets.join(' | '),
    country: g.countries.join(', '),
  } });
}

return out;

// Node: Match Existing Record (runOnceForAllItems)
// Input 1: valid leads from "Remove Same-Batch Duplicates".
// Input 2: all Leads records from "Search Airtable — Existing Lead?" (one run, no filter).
const validLeads = $('Remove Same-Batch Duplicates').all()
  .map((i) => i.json)
  .filter((l) => l.is_valid_domain);

// Only real Airtable records count. An empty search result has no id.
const existing = $input.all()
  .map((i) => i.json)
  .filter((r) => typeof r.id === 'string' && r.id.startsWith('rec'));

// Map canonical_domain to record id. If duplicates exist, the first one wins.
const idByDomain = new Map();
for (const rec of existing) {
  const domain = (rec.fields || {}).canonical_domain;
  if (domain && !idByDomain.has(domain)) idByDomain.set(domain, rec.id);
}

return validLeads.map((lead) => {
  const id = idByDomain.get(lead.canonical_domain) || '';
  return { json: { ...lead, airtable_record_id: id, existing_record: id !== '' } };
});

// Node: Attach Record ID (runOnceForEachItem)
// Both the "Create New Lead" and "Update Existing Lead" branches feed this node.
// Each Airtable node returns the record id, so we take it from there and
// keep the lead fields from "Match Existing Record".
const lead = $('Match Existing Record').item.json;
const airtableResult = $input.item.json || {};

const id = airtableResult.id || lead.airtable_record_id;
if (!id) {
  throw new Error('No Airtable record id after create/update for ' + lead.canonical_domain);
}

return { json: { ...lead, airtable_record_id: id } };

// Node: Build Execution Summary (runOnceForAllItems)
// Runs after the lead loop finishes. Counts come from the Airtable records touched
// by this execution (last_execution_id), not from guesses. Field names are read
// with a fallback because the Airtable node may return fields flat or under "fields".
const leads = $input.all().map((i) => i.json).map((r) => r.fields || r);
const search = $('Parse Search Results').all().map((i) => i.json);
const dedupe = $('Remove Same-Batch Duplicates').all().map((i) => i.json);
const cfg = $('Config').first().json;

const count = (fn) => leads.filter(fn).length;

const summary = {
  execution_id: cfg.execution_id,
  organic_results_received: search.filter((x) => !x.parse_error).length,
  search_error_items: search.filter((x) => x.parse_error).length,
  unique_candidates: dedupe.filter((x) => x.is_valid_domain).length,
  duplicates_removed_in_batch: dedupe.reduce((s, x) => s + (x.is_valid_domain ? (x.duplicates_merged || 0) : 0), 0),
  invalid_urls_logged: dedupe.filter((x) => !x.is_valid_domain).length,
  new_airtable_records: count((l) => l.run_action === 'created'),
  existing_records_updated: count((l) => l.run_action === 'updated'),
  qualified: count((l) => l.qualification_status === 'Qualified'),
  needs_review: count((l) => l.qualification_status === 'Needs Review'),
  rejected: count((l) => l.qualification_status === 'Rejected'),
  missing_contact_emails: count((l) => !l.business_email),
  enrichment_failures: count((l) => l.enrichment_status === 'failed'),
};

return [{ json: summary }];

// Node: Find Contact and About Pages (runOnceForAllItems)
// Input: the homepage response for the current lead (batch size 1).
// Output: one item per candidate page (max 4), or one item with a skip_reason.
// Does not use the built-in URL class, so it works in every n8n environment.
const lead = $('Loop Over Leads').first().json;
const home = $input.first().json || {};
const MAX_PAGES = 4;
const leadId = lead.airtable_record_id || lead.canonical_domain;

const skip = (reason) => [{ json: { lead_id: leadId, page_url: '', skip_reason: reason } }];

if (home.error) return skip('homepage_unavailable');

const html = typeof home.data === 'string' ? home.data : (typeof home.body === 'string' ? home.body : '');
if (!html) return skip('homepage_empty');

// Bot-protection pages are not the real homepage. Record it and do not try to get around it.
if (/aws-waf|awswaf|challenge\.js|captcha|cf-chl|just a moment/i.test(html)) {
  return skip('bot_protection_detected');
}

// Turn an href into a full URL. lead.website looks like "https://glowshop.co.uk".
function toAbsolute(href) {
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return 'https:' + href;
  if (href.startsWith('/')) return lead.website + href;
  return lead.website + '/' + href;
}

// Get the host from a full URL, without "www." and without a port.
function hostOf(absUrl) {
  const mm = absUrl.match(/^https?:\/\/([^\/?#]+)/i);
  return mm ? mm[1].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '') : '';
}

const candidates = [];
const linkRe = /<a\b[^>]*href\s*=\s*["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = linkRe.exec(html)) !== null) {
  const href = m[1].trim();
  if (/^(mailto|tel|javascript):/i.test(href)) continue;

  const abs = toAbsolute(href);
  const host = hostOf(abs);

  // Same site only. Subdomains count, for example shop.glowshop.co.uk.
  const sameSite = host === lead.canonical_domain || host.endsWith('.' + lead.canonical_domain);
  if (!sameSite) continue;

  // Remove query strings and fragments (tracking parameters), keeping the path.
  const clean = abs.split(/[?#]/)[0];
  const path = clean.replace(/^https?:\/\/[^\/]+/i, '').toLowerCase();
  const linkText = m[2].replace(/<[^>]+>/g, ' ').toLowerCase();

  const relevant = /about|contact|brand|stockist|who-we-are|our-story|get-in-touch/.test(path + ' ' + linkText);
  if (relevant && !candidates.includes(clean)) candidates.push(clean);
}

const chosen = candidates.slice(0, MAX_PAGES);
if (chosen.length === 0) return skip('no_candidate_pages_found');

return chosen.map((url) => ({ json: { lead_id: leadId, page_url: url, skip_reason: '' } }));

// Node: Attach Page Body (runOnceForEachItem)
// The HTTP Request node replaces the item with the response, so we re-attach
// the page URL from "Find Contact and About Pages" (paired item).
const meta = $('Find Contact and About Pages').item.json;
const resp = $input.item.json || {};

const html = typeof resp.data === 'string' ? resp.data : (typeof resp.body === 'string' ? resp.body : '');
const fetchError = resp.error ? String(resp.error.message || resp.error) : '';

return { json: {
  page_url: meta.page_url,
  html,
  fetch_error: fetchError,
} };

// Node: Assemble Website Evidence (runOnceForAllItems)
// Runs once per lead (the loop uses batch size 1).
// Builds the only text the LLM is allowed to see: the homepage plus the candidate pages.
// Keeps the URL of each page, so every LLM claim can be checked against a real source.
const lead = $('Loop Over Leads').first().json;
const homeRaw = $('Fetch Homepage').first().json || {};

const MAX_PAGE_CHARS = 8000;
const MAX_TOTAL_CHARS = 24000;

const bodyOf = (r) => (typeof r.data === 'string' ? r.data : (typeof r.body === 'string' ? r.body : ''));

// Pull visible text out of HTML. Mailto and tel links are kept because the
// address is inside the href attribute, which tag stripping would otherwise remove.
function pageText(html) {
  const mailtos = [...html.matchAll(/mailto:([^"'?\s>]+)/gi)].map((x) => x[1]);
  const tels = [...html.matchAll(/tel:([^"'\s>]+)/gi)].map((x) => x[1]);
  const visible = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
  const extra = [
    mailtos.length ? 'Mailto links found: ' + mailtos.join(', ') : '',
    tels.length ? 'Tel links found: ' + tels.join(', ') : '',
  ].filter(Boolean).join(' . ');
  return (visible + ' ' + extra).trim().slice(0, MAX_PAGE_CHARS);
}

const pages = [];
const fetchLog = [];

function addPage(url, html, err) {
  if (err) {
    fetchLog.push({ url, error: err });
    pages.push({ url, text: '', status: 'error' });
    return;
  }
  const text = pageText(html);
  pages.push({ url, text, status: text.length > 0 ? 'ok' : 'empty' });
}

addPage(lead.website, bodyOf(homeRaw), homeRaw.error ? String(homeRaw.error.message || homeRaw.error) : '');

for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.page_url) continue; // skipped items from the IF "Has Candidate Pages?" false branch
  addPage(j.page_url, j.html || '', j.fetch_error || '');
}

// Enforce a total size limit so the prompt stays small and predictable.
let total = 0;
const kept = [];
for (const p of pages.filter((p) => p.status === 'ok')) {
  const room = MAX_TOTAL_CHARS - total;
  if (room <= 0) break;
  const text = p.text.slice(0, room);
  total += text.length;
  kept.push({ ...p, text });
}

const evidenceText = kept.map((p) => `[PAGE ${p.url}]\n${p.text}`).join('\n\n');

return [{ json: {
  ...lead,
  pages: kept,
  fetch_log: fetchLog,
  evidence_text: evidenceText,
  allowed_urls: kept.map((p) => p.url),
  has_evidence: kept.some((p) => p.text.length >= 200),
} }];

// Node: Build LLM Prompt (runOnceForAllItems)
// Builds two prompts for the AI Agent:
// system_prompt = rules and output schema (fixed for every lead)
// user_prompt   = this lead's page text, plus retry notes if the last attempt failed
const j = $input.first().json;
const attempt = (j.attempt || 0) + 1;
const priorErrors = Array.isArray(j.validation_errors) ? j.validation_errors : [];

const system_prompt = `You are a precise data extractor for B2B lead research. You cannot browse the web. You only use the text you are given.

Rules:
- Use only information written in the PAGES. Never use outside knowledge.
- Each field has a status: "found" (stated on a page), "inferred" (follows from page content; explain in note), or "not_found" (value null or []).
- For found or inferred, source_url must be one of the PAGE URLs.
- Copy names, emails, phone numbers and brands exactly as written.
- Never invent a value. If it is missing, use not_found.
- Return one JSON object and nothing else. No markdown.

Fields:
- business_description (string)
- business_model: multi_brand_retailer | single_brand_retailer | manufacturer_own_brand | marketplace | service_provider | other | unknown
- product_categories (array of strings)
- third_party_brands (array of brand names it stocks, not its own)
- ecommerce_evidence (string: shopping features shown, such as basket or checkout)
- contact_person (a named individual only; team names do not count)
- business_email
- business_phone
- country: United Kingdom | United States | Canada | Australia | Other

Each field is: {"value": ..., "status": "found|inferred|not_found", "source_url": "...", "note": "..."}`;

const retryNote = attempt > 1
  ? '\nYour previous answer failed these checks. Fix them without adding new facts:\n- ' + priorErrors.join('\n- ') + '\n\n'
  : '';

const pagesBlock = (j.pages || [])
  .map((p) => '=== PAGE: ' + p.url + ' ===\n' + p.text)
  .join('\n\n');

const user_prompt = `${retryNote}PAGES:\n${pagesBlock}`;

return [{ json: { ...j, attempt, system_prompt, user_prompt } }];

// Node: Validate Enrichment Output (runOnceForEachItem)
// Input: the AI Agent output. The model's text is in $json.output.
// Context: the lead data and page text from Build LLM Prompt.
const ctx = $('Build LLM Prompt').item.json;
const resp = $input.item.json || {};

let maxAttempts = 2;
try {
  maxAttempts = Number($('Config').first().json.max_llm_attempts) || 2;
} catch (e) {
  maxAttempts = 2;
}

const errors = [];
let data = null;

if (resp.error) errors.push('llm_request_failed: ' + String(resp.error.message || resp.error));

const text = String(resp.output || '').trim();
if (!resp.error && !text) errors.push('llm_empty_output');

if (text) {
  // Remove a markdown code fence if the model adds one.
  const cleaned = text.replace(/^```(json)?\s*/i, '').replace(/```\s*$/, '');
  try {
    data = JSON.parse(cleaned);
  } catch (e) {
    errors.push('invalid_json');
  }
}

const FIELDS = [
  'business_description', 'business_model', 'product_categories', 'third_party_brands',
  'ecommerce_evidence', 'contact_person', 'business_email', 'business_phone', 'country',
];
const STATUSES = ['found', 'inferred', 'not_found'];
const MODELS = ['multi_brand_retailer', 'single_brand_retailer', 'manufacturer_own_brand', 'marketplace', 'service_provider', 'other', 'unknown'];
const COUNTRIES = ['United Kingdom', 'United States', 'Canada', 'Australia', 'Other'];
// These values must appear word-for-word in the page text when marked "found".
const LITERAL_CHECK_FIELDS = ['contact_person', 'business_email', 'business_phone', 'third_party_brands'];

const normUrl = (u) => String(u || '').trim().replace(/\/+$/, '').toLowerCase();
const allowed = new Set((ctx.allowed_urls || []).map(normUrl));
const evidence = String(ctx.evidence_text || '').toLowerCase();
const evidenceDigits = evidence.replace(/\D/g, '');

if (data && typeof data === 'object') {
  for (const field of FIELDS) {
    const f = data[field];
    if (!f || typeof f !== 'object') {
      errors.push(`${field}: missing or not an object`);
      continue;
    }
    if (!STATUSES.includes(f.status)) {
      errors.push(`${field}: invalid status "${f.status}"`);
      continue;
    }

    const v = f.value;
    const empty = v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);

    if (f.status === 'not_found') {
      if (!empty) errors.push(`${field}: status not_found but a value is present`);
      continue;
    }
    if (empty) {
      errors.push(`${field}: status ${f.status} but value is empty`);
      continue;
    }

    if (!f.source_url || !allowed.has(normUrl(f.source_url))) {
      errors.push(`${field}: source_url is missing or is not one of the fetched pages`);
    }

    if (f.status === 'found' && LITERAL_CHECK_FIELDS.includes(field)) {
      const values = Array.isArray(v) ? v : [v];
      for (const item of values) {
        const s = String(item).toLowerCase();
        if (field === 'business_phone') {
          const digits = s.replace(/\D/g, '');
          if (digits.length < 6 || !evidenceDigits.includes(digits)) {
            errors.push(`${field}: "${item}" marked found but its digits do not appear in the page text`);
          }
        } else if (!evidence.includes(s)) {
          errors.push(`${field}: "${item}" marked found but does not appear in the page text`);
        }
      }
    }
  }

  const model = data.business_model && data.business_model.value;
  if (data.business_model && model !== null && model !== undefined && !MODELS.includes(model)) {
    errors.push(`business_model: "${model}" is not an allowed value`);
  }

  const country = data.country && data.country.value;
  if (data.country && country !== null && country !== undefined && !COUNTRIES.includes(country)) {
    errors.push(`country: "${country}" is not an allowed value`);
  }

  const email = data.business_email && data.business_email.value;
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
    errors.push(`business_email: "${email}" has invalid format`);
  }

  // Contradiction check: a multi-brand retailer must list at least two third-party brands.
  const brands = data.third_party_brands && Array.isArray(data.third_party_brands.value) ? data.third_party_brands.value : [];
  if (model === 'multi_brand_retailer' && brands.length < 2) {
    errors.push('contradiction: business_model is multi_brand_retailer but fewer than 2 third-party brands are listed');
  }
}

const valid = errors.length === 0;

return { json: {
  ...ctx,
  enrichment: data,
  validation_errors: errors,
  is_valid: valid,
  llm_request_ok: !resp.error,
  retry_allowed: !valid && ctx.attempt < maxAttempts,
} };

// Node: Qualify Retailer (runOnceForEachItem)
// Deterministic rules decide the outcome. The LLM only supplies evidence.
// Hard exclusions come first and cannot be overridden by the LLM.
// Qualified requires directly found evidence for every key criterion.
const j = $input.item.json;
const e = j.enrichment || null;
const usable = Boolean(e) && j.is_valid === true && j.has_evidence !== false;

const TARGET = ['United Kingdom', 'United States', 'Canada', 'Australia'];
// Starter list of large chains and marketplaces, matched on the first domain label.
const LARGE_CHAIN_OR_MARKETPLACE = new Set([
  'amazon', 'ebay', 'walmart', 'target', 'sephora', 'ulta', 'boots', 'superdrug',
  'asos', 'lookfantastic', 'notino', 'iherb', 'tesco', 'costco', 'macys', 'nordstrom',
  'shopee', 'etsy',
]);

const get = (k) => (e && e[k] ? e[k] : { status: 'not_found', value: null, source_url: null });
const found = (k) => get(k).status === 'found';
const brands = found('third_party_brands') && Array.isArray(get('third_party_brands').value) ? get('third_party_brands').value : [];

const firstLabel = (j.canonical_domain || '').split('.')[0];
const hardExclusions = [];
const missing = [];

if (LARGE_CHAIN_OR_MARKETPLACE.has(firstLabel)) {
  hardExclusions.push('Domain matches the starter list of large chains or marketplaces.');
}
if (usable) {
  const model = get('business_model').value;
  if (found('business_model') && ['manufacturer_own_brand', 'marketplace', 'service_provider'].includes(model)) {
    hardExclusions.push(`The site identifies its business model as ${model}.`);
  }
  if (found('country') && !TARGET.includes(get('country').value)) {
    hardExclusions.push(`The country shown on the site is outside the target market (${get('country').value}).`);
  }
  if (found('product_categories')) {
    const cats = (get('product_categories').value || []).join(' ').toLowerCase();
    if (!/skin|beauty|cosmetic|serum|cleanser|moistur|sunscreen|makeup|toner|mask/.test(cats)) {
      hardExclusions.push('The product categories found are not skincare or beauty.');
    }
  }
}

let qualificationStatus;
let reason;

if (hardExclusions.length > 0) {
  qualificationStatus = 'Rejected';
  reason = hardExclusions.join(' ');
} else if (!j.has_evidence) {
  qualificationStatus = 'Needs Review';
  reason = 'No usable public website text was retrieved, so the lead cannot be assessed.';
} else if (!usable) {
  qualificationStatus = 'Needs Review';
  reason = 'The LLM output failed validation: ' + (j.validation_errors || []).join('; ');
} else {
  if (!(found('business_model') && get('business_model').value === 'multi_brand_retailer')) missing.push('multi-brand retailer model');
  if (brands.length < 2) missing.push('at least two third-party brands');
  if (!found('ecommerce_evidence')) missing.push('e-commerce evidence');
  if (!(found('country') && TARGET.includes(get('country').value))) missing.push('target country');
  if (!found('product_categories')) missing.push('product categories');

  if (missing.length > 0) {
    qualificationStatus = 'Needs Review';
    reason = 'Directly found evidence is missing for: ' + missing.join(', ') + '.';
  } else {
    qualificationStatus = 'Qualified';
    reason = `Multi-brand skincare retailer with ${brands.length} third-party brands (${brands.join(', ')}), e-commerce evidence and a target-market country, all found on the site.`;
  }
}

const enrichmentStatus = !j.has_evidence ? 'no_content' : (!usable ? 'failed' : 'ok');
const sourceUrls = new Set(j.discovery_urls || []);
if (e) {
  for (const k of Object.keys(e)) {
    if (e[k] && e[k].source_url) sourceUrls.add(e[k].source_url);
  }
}

return { json: {
  ...j,
  qualification_status: qualificationStatus,
  qualification_reason: reason,
  enrichment_status: enrichmentStatus,
  validation_errors_text: (j.validation_errors || []).join('; '),
  processing_status: qualificationStatus === 'Qualified' ? 'qualified' : (qualificationStatus === 'Rejected' ? 'rejected' : 'needs_review'),
  category: found('product_categories') ? (get('product_categories').value || []).join(', ') : '',
  business_model: found('business_model') ? get('business_model').value : 'unknown',
  contact_person: found('contact_person') ? get('contact_person').value : '',
  business_email: found('business_email') ? get('business_email').value : '',
  phone: found('business_phone') ? get('business_phone').value : '',
  ecommerce_evidence: found('ecommerce_evidence') ? get('ecommerce_evidence').value : '',
  multi_brand_evidence: brands.join(', '),
  country: found('country') ? get('country').value : (j.country || 'unknown'),
  evidence_urls: [...sourceUrls].join('\n'),
  enrichment_json: JSON.stringify(e || { error: 'no enrichment output' }, null, 2),
} };

// Node: Validate Email Syntax (runOnceForEachItem)
// Syntax check only. There is no SMTP probing and no DNS/MX check in v1.
// Finding an address on a website never makes it "verified".
const j = $input.item.json;
const email = String(j.business_email || '').trim();

let emailStatus;
if (!email) {
  emailStatus = 'missing';
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  emailStatus = 'invalid_format';
} else {
  emailStatus = 'found_unchecked';
}

// Informational only: does the email's domain match the lead's domain?
const emailDomain = email.includes('@') ? email.split('@')[1].toLowerCase() : '';
const emailDomainMatchesSite = Boolean(emailDomain) && (emailDomain === j.canonical_domain || emailDomain.endsWith('.' + j.canonical_domain));

return { json: {
  ...j,
  email_status: emailStatus,
  email_domain_matches_site: emailDomainMatchesSite,
} };
